using System.IO;
using System.Text.Json;
using System.Windows;
using System.Windows.Media;
using System.Windows.Media.Imaging;
using VisionFramework;
using VisionPluginContracts;
using VisionPlugins.DistortionCalibration;
static class Program {
 [STAThread] static int Main(){try{Run();return 0;}catch(Exception error){Console.Error.WriteLine(error);return 1;}}
 static void Run(){int checks=0;void Check(bool value,string message){checks++;if(!value)throw new Exception(message);}var values=DistortionCalibrationMetadata.Defaults();bool reject=false;var context=new ToolEditorContext(new("distortion",DistortionCalibrationMetadata.ModuleId,"1.0.0","畸变标定",values),Directory.GetCurrentDirectory(),next=>{if(reject)throw new InvalidOperationException("Owned host rejection");values=next;},_=>throw new InvalidOperationException("Execution owner not attached in model-only test"));using var session=new DistortionCalibrationConfigurationProvider((_,_)=>throw new InvalidOperationException("Numerical owner not attached")).CreateConfiguration(context);var state=session.State;
 Check(state.Definition.Tabs.Count==3,"Original three tabs");Check(state.Find("HomoFreedom")!.Value=="1"&&state.Find("CalibBoardWeightFun")!.Value=="2"&&state.Find("Circularity")!.Value=="50","Module backend Algorithm.xml initialization overrides SDK and control-only declarations");Check(!state.Find("PointErrorThreshold")!.Visible&&!state.Find("OutputPostCorrectionEnable")!.Visible,"Original evaluation fields initially hidden");state.CommitUser("DistortionEvaluationEnable","True");Check(state.Find("PointErrorThreshold")!.Visible&&state.Find("OutputPostCorrectionEnable")!.Visible,"Source evaluation visibility trigger");state.CommitUser("CorrectCenterPointInput","1");Check(state.Find("CorrectCenterPointX")!.Visible&&state.Find("CorrectCenterPointY")!.Visible&&!state.Find("CorrectCenterPoint")!.Visible,"Original scalar correction-center selection");Check(JsonSerializer.Deserialize<Dictionary<string,string>>(values["ConfigurationUserData"].GetString()!)!["Param.CorrectCenterPointInput"]=="1","Input selector uses source UI-only user-data domain");state.CommitUser("CalibBoardType","2");Check(state.Find("Circularity")!.Visible&&state.Find("EdgeThresh")!.Visible&&!state.Find("FilterStatus")!.Visible,"Original circle mode controls");state.CommitUser("CalibBoardType","1");Check(!state.Find("Circularity")!.Visible&&state.Find("FilterStatus")!.Visible,"Checker branch restores source controls");reject=true;state.CommitUser("WeightFactor","30");Check(state.Find("WeightFactor")!.Value=="20"&&values["WeightFactor"].GetInt32()==20,"Rejected backend write restores value");reject=false;foreach(int mode in new[]{1,2,3}){state.CommitUser("CorrectModel",mode.ToString());Check(values["CorrectModel"].GetInt32()==mode,"Original model value "+mode);}
 // Node parameter payload is the plugin persistence seam; this checks actual
 // provider reconstruction, not the outer framework solution-file encoding.
 var persisted=JsonSerializer.Deserialize<Dictionary<string,JsonElement>>(JsonSerializer.Serialize(values))!;
 using(var reopened=new DistortionCalibrationConfigurationProvider((_,_)=>throw new InvalidOperationException("No export requested")).CreateConfiguration(context with{Node=context.Node with{Parameters=persisted}})){
 Check(reopened.State.Find("CorrectModel")!.Value=="3","Model survives parameter serialization/reopen");
 Check(reopened.State.Find("CorrectCenterPointX")!.Visible&&!reopened.State.Find("CorrectCenterPoint")!.Visible,"User-data selector restores dependent visibility");
 Check(reopened.State.Find("OutputPostCorrectionEnable")!.Visible,"Evaluation enable restores dependent controls");
 Check(reopened.State.Find("WeightFactor")!.Value=="20","Rejected value does not leak into reopened configuration");
 }
 var window=new ToolConfigurationModelWindow(context,session){Left=-10000,Top=-10000,WindowStartupLocation=WindowStartupLocation.Manual};window.Show();window.UpdateLayout();string directory="analysis/distortion-calibration/configuration";Directory.CreateDirectory(directory);void Capture(string name){window.UpdateLayout();var image=new RenderTargetBitmap((int)window.ActualWidth,(int)window.ActualHeight,96,96,PixelFormats.Pbgra32);image.Render(window);var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var file=File.Create(Path.Combine(directory,name+".png"));encoder.Save(file);}Capture("basic");T? Find<T>(DependencyObject e)where T:DependencyObject{if(e is T found)return found;for(int i=0;i<VisualTreeHelper.GetChildrenCount(e);i++)if(Find<T>(VisualTreeHelper.GetChild(e,i)) is {} child)return child;return null;}var tabs=Find<System.Windows.Controls.TabControl>(window)!;tabs.SelectedIndex=1;Capture("run");tabs.SelectedIndex=2;Capture("display");var diagnostics=window.ConfigurationView.Diagnostics.ToArray();window.Close();File.WriteAllText(Path.Combine(directory,"verification.json"),JsonSerializer.Serialize(new{checks,diagnostics,productionCommonModel=true,complete=false,originalDesktopCompared=false,nativeNumericalOwnerAttached=false},new JsonSerializerOptions{WriteIndented=true}));Console.WriteLine($"Distortion model checks passed: {checks}; remaining render diagnostics: {JsonSerializer.Serialize(diagnostics)}");
 }
}

